package com.yeyamo_mobile.api.moderation_trust_service.infrastructure.audit;import java.util.*;import org.springframework.data.domain.PageRequest;import org.springframework.stereotype.Component;import com.yeyamo_mobile.api.moderation_trust_service.application.port.ModerationAuditPort;import com.yeyamo_mobile.api.moderation_trust_service.domain.model.AuditEntry;
@Component public class JpaModerationAuditAdapter implements ModerationAuditPort{private final SpringAuditRepository repo;public JpaModerationAuditAdapter(SpringAuditRepository r){repo=r;}public void append(AuditEntry a){var e=new AuditEntryEntity();e.setId(a.id());e.setAction(a.action());e.setAggregateType(a.aggregateType());e.setAggregateId(a.aggregateId());e.setActorId(a.actorId());e.setCorrelationId(a.correlationId());e.setDetails(a.details());e.setOccurredAt(a.occurredAt());repo.save(e);}public List<AuditEntry>latest(int limit){return repo.findAllByOrderByOccurredAtDesc(PageRequest.of(0,limit)).stream().map(e->new AuditEntry(e.getId(),e.getAction(),e.getAggregateType(),e.getAggregateId(),e.getActorId(),e.getCorrelationId(),e.getDetails(),e.getOccurredAt())).toList();}}
